# Julia twin of Bench/Math.lean (`math` suite): Base's exp/log/expm1/log1p/^ over sweeps of
# n = 10⁴ arguments folded into a sum, generated by repeated addition exactly as in Lean.
#   julia --startup-file=no --project=<env> oracle/bench/math.jl [--json out.json]
isdefined(Main, :BenchHarness) || include(joinpath(@__DIR__, "harness.jl"))
using .BenchHarness

function sweep(f::F, x::Float64, dx::Float64, n::Int) where {F}
    acc = 0.0
    for _ in 1:n
        acc += f(x)
        x += dx
    end
    acc
end
function sweep2(f::F, x::Float64, dx::Float64, y::Float64, n::Int) where {F}
    acc = 0.0
    for _ in 1:n
        acc += f(x, y)
        x += dx
    end
    acc
end
pow7(x) = x^7

function suite_math(ctx)
    n = 10000
    p = "n=$n"
    ex = 1400.0 / n
    bench!(ctx, "exp"; ops = n, param = p) do i
        sweep(exp, blackbox(i, -700.0), ex, n)
    end
    lx = 1.0e6 / n
    bench!(ctx, "log"; ops = n, param = p) do i
        sweep(log, blackbox(i, 1.0e-3), lx, n)
    end
    bench!(ctx, "expm1"; ops = n, param = p) do i
        sweep(expm1, blackbox(i, -2.0), 4.0 / n, n)
    end
    bench!(ctx, "log1p"; ops = n, param = p) do i
        sweep(log1p, blackbox(i, -0.5), 4.0 / n, n)
    end
    px = 100.0 / n
    bench!(ctx, "pow_2.5"; ops = n, param = p) do i
        sweep2(^, blackbox(i, 1.0e-3), px, 2.5, n)
    end
    bench!(ctx, "pow_int7"; ops = n, param = p) do i
        sweep(pow7, blackbox(i, 1.0e-3), px, n)
    end
end

register!("math", suite_math)
(abspath(PROGRAM_FILE) == @__FILE__) && main_suites(["math" => suite_math])
